@MainActor
final class VM {
    var text = ""
    func load() async {
        let value = await api.fetch()
        text = value
    }
}

actor Counter {
    var value = 0
    func incrementSlowly() async {
        let old = value
        await Task.yield()
        value = old + 1
    }
}

let currentID = UUID()
latestRequestID = currentID
let result = try await api.fetch()
guard latestRequestID == currentID else { return }
state = result

func load() async throws -> Data {
    try Task.checkCancellation()
    let data = try await api.fetch()
    try Task.checkCancellation()
    return data
}

let items = try await withThrowingTaskGroup(of: Item.self) { group in
    for id in ids { group.addTask { try await api.item(id) } }
    var out: [Item] = []
    for try await item in group { out.append(item) }
    return out
}

enum Status: Decodable {
    case active, disabled, unknown(String)
    init(from decoder: Decoder) throws {
        let raw = try decoder.singleValueContainer().decode(String.self)
        switch raw {
        case "active": self = .active
        case "disabled": self = .disabled
        default: self = .unknown(raw)
        }
    }
}
